#!/usr/bin/env python3
"""Split the selected OpenWrt package build dirs into N balanced groups.

Inputs (generated by a normal openwrt `make defconfig`):
  .config            -- resolved config, all selected CONFIG_PACKAGE_*=y
  tmp/.packagedeps   -- generated by scripts/package-metadata.pl mk, contains:
        package-$(CONFIG_PACKAGE_<pkg>) += <dir>       (selected package -> builddir)
        package- += <dir>                              (always-built / buildonly)
        $(curdir)/<dir>/compile += $(curdir)/<dep>/compile   (build dependency edges)
        $(curdir)/<dir>/variants += ...                (variants, ignored here)

Output: a GitHub Actions matrix JSON on stdout:
  {"include":[{"group":"g1","dirs":"dirA dirB ...","ndirs":"12"}, ...]}

We group whole directory clusters (e.g. feeds/packages/libs) so that most build
deps stay inside one group; a build dep that still crosses a group boundary is
built redundantly by make itself (tmp/.packagedeps adds it as a prerequisite),
which is harmless and costs only parallel time.
"""
import json
import re
import sys

CONFIG_RE = re.compile(r"^(CONFIG_[A-Za-z0-9_.+-]+)=y$", re.M)
PKG_LINE = re.compile(r"^package-\$\(CONFIG_PACKAGE_([A-Za-z0-9_.+-]+)\) \+= (\S+)\s*$")
ALWAYS_LINE = re.compile(r"^package- \+= (\S+)\s*$")
DEP_LINE = re.compile(r"^\$\(curdir\)/([^:]+?)/compile \+= (.+)$")
DEP_ITEM = re.compile(r"\$\(curdir\)/(.+?)/compile")
COND_DEP = re.compile(r"^\$\(if \$\(CONFIG_PACKAGE_([A-Za-z0-9_.+-]+)\),\$\(curdir\)/(.+?)/compile\)$")


def main() -> int:
    cfg_path, deps_path, n_str = sys.argv[1], sys.argv[2], sys.argv[3]
    n = int(n_str)
    cfg = open(cfg_path, encoding="utf-8", errors="replace").read()
    selected = set(CONFIG_RE.findall(cfg))

    dirs = set()
    always_dirs = set()
    cond_dirs = {}          # dir -> CONFIG_PACKAGE_* symbol referenced by packagedeps
    for line in open(deps_path, encoding="utf-8", errors="replace"):
        m = PKG_LINE.match(line)
        if m:
            sym = "CONFIG_PACKAGE_" + m.group(1)
            if sym in selected:
                dirs.add(m.group(2))
            else:
                cond_dirs[m.group(2)] = sym
            continue
        m = ALWAYS_LINE.match(line)
        if m:
            always_dirs.add(m.group(1))
            continue

    # package/Makefile unconditionally does: package-y += kernel/linux
    dirs.add("kernel/linux")

    import os
    tree = os.path.dirname(os.path.abspath(cfg_path))

    def has_runtime_mf(mf):
        """True/False when the dir Makefile can be classified, None if unknown.

        A dir is build-only iff every `define Package/<name>` block contains
        BUILDONLY:=1.  `define Package/<name>/description|install|conffiles` are
        sub-blocks of the package and must not be treated as separate packages
        (websocketpp/easyloggingpp etc. would otherwise be misclassified).
        """
        if not os.path.isfile(mf):
            return None
        try:
            txt = open(mf, encoding="utf-8", errors="replace").read()
        except OSError:
            return None
        blocks = re.split(r"\ndefine\s+(?:Kernel)?Package/[A-Za-z0-9_.+-]+\n", txt)
        if len(blocks) <= 1:
            return None
        for b in blocks[1:]:
            if "BUILDONLY:=1" not in re.sub(r"\s+", "", b):
                return True
        return False

    # `package- += dir`: dirs whose packages are all BUILDONLY (skipped by world,
    # built on demand via dependency edges).  A few essential dirs may also show
    # up here; keep those whose Makefile has at least one non-build-only package.
    always_keep = set()
    for d in sorted(always_dirs):
        if has_runtime_mf(os.path.join(tree, "package", d, "Makefile")) is not False:
            always_keep.add(d)
    dirs |= always_keep

    # `package-$(CONFIG_PACKAGE_x) += dir` where CONFIG_PACKAGE_x is completely
    # absent from .config: world builds these (e.g. base-files / libs/toolchain are
    # pulled in by the target DEFAULT_PACKAGES, not by a visible CONFIG symbol).
    defined_syms = set(re.findall(r"^#?\s*(CONFIG_[A-Za-z0-9_.+-]+)", cfg, re.M))
    cond_keep = set()
    for d, sym in sorted(cond_dirs.items()):
        if sym in defined_syms or d in dirs:
            continue
        if has_runtime_mf(os.path.join(tree, "package", d, "Makefile")) is not False:
            cond_keep.add(d)
    dirs |= cond_keep
    buildonly_skipped = sorted(always_dirs - always_keep)
    # keep the list deterministic and drop obviously bogus entries
    dirs = sorted(d for d in dirs if not d.startswith("-") and os.path.isdir(os.path.join(tree, "package", d)))

    # dependency edges (only for reporting / clustering sanity)
    edges = {}
    for line in open(deps_path, encoding="utf-8", errors="replace"):
        m = DEP_LINE.match(line)
        if not m:
            continue
        src = m.group(1)
        dsts = []
        for item in m.group(2).split():
            ci = COND_DEP.match(item)
            if ci:
                if "CONFIG_PACKAGE_" + ci.group(1) in selected:
                    dsts.append(ci.group(2))
                continue
            di = DEP_ITEM.match(item)
            if di:
                dsts.append(di.group(1))
        if dsts:
            edges[src] = set(dsts)

    def weight(d):
        w = 1
        base = d.rsplit("/", 1)[-1]
        if d == "kernel/linux":
            return 8
        if "kmod" in base or base.startswith("kmod-"):
            w += 1
        if base in ("golang", "rust", "llvm-bpf", "node", "python3", "perl", "meson", "cmake"):
            w += 2
        if d.startswith("feeds/packages/libs/"):
            w += 1
        return w

    def cluster_of(d):
        parts = d.split("/")
        # keep every kernel/kmod build dir in one cluster: they share the kernel
        # build tree and the kernel package, so spreading them over groups would
        # duplicate the expensive kernel-package step in every group.
        if "kernel" in parts[:4]:
            return "kernel"
        if parts[0] == "feeds" and len(parts) >= 3:
            return "/".join(parts[:3])
        if len(parts) >= 2:
            return "/".join(parts[:2])
        return parts[0]

    clusters = {}
    for d in dirs:
        clusters.setdefault(cluster_of(d), []).append(d)

    cl_weight = {c: sum(weight(d) for d in ds) for c, ds in clusters.items()}
    # biggest clusters first, greedy onto the least loaded group
    order = sorted(clusters, key=lambda c: (-cl_weight[c], c))
    groups = [{"name": "g%d" % (i + 1), "dirs": [], "weight": 0} for i in range(n)]
    for c in order:
        g = min(groups, key=lambda x: (x["weight"], x["name"]))
        g["dirs"].extend(sorted(clusters[c]))
        g["weight"] += cl_weight[c]

    include = []
    for g in groups:
        include.append({
            "group": g["name"],
            "ndirs": str(len(g["dirs"])),
            "weight": str(g["weight"]),
            "dirs": " ".join(sorted(g["dirs"])),
        })

    # human readable summary on stderr (visible in the job log)
    print("=== parallel build plan ===", file=sys.stderr)
    print("selected build dirs: %d, dep edges: %d, groups: %d" % (len(dirs), len(edges), n),
          file=sys.stderr)
    print("always dirs kept (non-build-only): %d" % len(always_keep), file=sys.stderr)
    print("essential dirs with absent CONFIG symbol scheduled: %d" % len(cond_keep), file=sys.stderr)
    for d in sorted(cond_keep):
        print("  essential %s" % d, file=sys.stderr)
    print("build-only dirs not scheduled (built on demand): %d" % len(buildonly_skipped),
          file=sys.stderr)
    for d in buildonly_skipped:
        print("  skip %s" % d, file=sys.stderr)
    for g in groups:
        print("  %s: %2d dirs (weight %d)" % (g["name"], len(g["dirs"]), g["weight"]),
              file=sys.stderr)
    print("=== end plan ===", file=sys.stderr)

    print(json.dumps({"include": include}, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
